    need(mapped['image_sha256']==record['image_sha256']and mapped['hardware_inputs_sha256']==record['hardware_inputs_sha256']
         ==hashlib.sha256(canonical(inputs)).hexdigest(),'Mapped audit image/source inventory differs')
    exp='project/fpga/token_only_model0_ddr_board1/fixed_attention0/rtl/board1_fixed_attention_exp_lut_sync.sv'
