def check(package,strict=True):
    require_v8_baseline_scope()
    need(SOURCE_REVIEWED is True,'V8 SHA2 portable source is not approved; no current release is admitted')
    package=Path(package).resolve();manifest=read(package/'MANIFEST.json')
    for name,want in manifest['files'].items():need(identity(target(package,name))==want,'Recipient file changed: '+name)
    for path in package.rglob('*'):
        if '.git'not in path.relative_to(package).parts:need(not path.is_symlink(),'Linked recipient path')
    if strict:need({p.relative_to(package).as_posix()for p in package.rglob('*')if not p.is_dir()and'.git'not in p.relative_to(package).parts}==set(manifest['files'])|{'MANIFEST.json'},'Unlisted/missing recipient file')
    record=read(package/'CANDIDATE.json')
    need(record['schema']=='long-context-private-recipient-v1'and record['phase']=='before-browser'
         and record['actual_browser_test_passed']is False and record['release_qualified']is False
         and record['timing_qualified']is False and record['configuration_independently_attested']is False,'Recipient stage/qualification scope differs')
    need(record['image_sha256']!=OLD_IMAGE and identity(package/'prebuilt/seeded-sampling/project/impl/pnr/shared_product.fs')['sha256']==record['image_sha256'],'New candidate image differs')
    need(identity(package/'assets/board1-real-semantic-image2048.bin')['sha256']==MODEL==record['model_image_sha256'],'Model asset changed')
    inputs=read(package/'host-app/hardware-inputs-seeded-sampling.json');need(len(inputs)==91 and inputs==record['native_source_sha256'],'Native91 association differs')
    digest=hashlib.sha256(canonical(inputs)).hexdigest();need(digest==record['hardware_inputs_sha256'],'Canonical hardware inventory differs')
    tested=record['model_tested_source_sha256'];need(set(tested)==set(inputs)and len(tested)==91,'Model-tested91 census differs')
    changes=sorted(n for n in inputs if inputs[n]!=tested[n])
    need(changes==record['implementation_only_source_changes']==['run.tcl']
         and hashlib.sha256(canonical(tested)).hexdigest()==record['model_tested_inventory_sha256'],'Model/native input roles differ')
    native_recipe=(package/'variants/seeded-sampling/hardware/run.tcl').read_bytes()
    recipe=implementation_recipe(native_recipe,tested['run.tcl'])
    need(record['implementation_recipe']==recipe,'V8 SHA2 implementation-recipe metadata differs')
    source=read(package/'variants/seeded-sampling/SOURCE.json');omitted=source['omitted_vendor_inputs']
    need(len(omitted)==4 and all(n.startswith('project/official/')and inputs[n]==p for n,p in omitted.items()),'Vendor provenance boundary differs')
    for name,pin in inputs.items():
        if name not in omitted:need(identity(package/'variants/seeded-sampling/hardware'/name)['sha256']==pin,'Distributed source87 differs: '+name)
    need(source['schema']=='fixed-seeded-source-binding-v8-baseline-selected-native'and source['image_sha256']==record['image_sha256']and source['native_inputs']==91 and source['distributable_inputs']==87,'SOURCE association differs')
    need(source['model_tested_native_inventory_sha256']==record['model_tested_inventory_sha256']
         and source['model_assembly_receipt_sha256']==record['model_assembly_receipt_sha256']
         and source['implementation_only_source_changes']==changes,'SOURCE model/native roles differ')
    need(source['implementation_recipe']==recipe,'SOURCE V8 SHA2 recipe scope differs')
    build=read(package/'prebuilt/seeded-sampling/BUILD.json')
    need(build['schema']=='fixed-fpga-local-build-v1'and build['variant']=='seeded-sampling'and build['image_sha256']==record['image_sha256']
         and build['hardware_inputs_sha256']==digest and build['flow_completed']is True and build['source_inputs_verified']is True
         and build['source_inputs_unchanged']is True and build['timing_qualified']is False,'Host prebuilt association differs')
    need(build['implementation_recipe']==recipe,'BUILD V8 SHA2 recipe scope differs')
    for name,want in record['host_source_inputs'].items():need(identity(package/name)==want,'Host source changed: '+name)
    profile=(package/'host-app/runtime_profile.py').read_text();need('@@CANDIDATE'not in profile and profile.count(digest)==1,'Runtime candidate inventory is not bound')
    cli=read(package/'evidence/seeded-sampling/current-candidate-cli.json')
    need(cli['schema']=='long-context-current-cli-public-v1'and cli['physical_campaign_schema']=='long-context-physical-campaign-v8-baseline-selected-native'
         and cli['image_sha256']==record['image_sha256']and cli['hardware_inputs_sha256']==digest
         and {r['suite']for r in cli['campaigns']}==SUITES and len(cli['campaigns'])==len(SUITES),'Current physical suite/image association differs')
    need(CURRENT_CLI_SHA is not None and identity(package/'evidence/seeded-sampling/current-candidate-cli.json')==record['cli_evidence']
         and record['cli_evidence']['sha256']==CURRENT_CLI_SHA,'Current CLI evidence changed or lacks actual final pin')
    need(identity(package/'reference/seeded-sampling/SOURCE.json')['sha256']==REFERENCE,'Independent model reference inventory changed')
    current_records(package,record,inputs,tested)
    cache_binding(package,record)
    mapped_binding(package,record,inputs)
    for suite in cli['campaigns']:
        need(suite['physical_fpga']is True and suite['image_sha256']==record['image_sha256']and suite['configuration_independently_attested']is False,'Recorded CLI hardware scope differs')
        for case in suite['cases']:
            case_tokens(case)
            reference=case['main_reference']
            if reference is not None:
                path=target(package,reference['path']);need(identity(path)['sha256']==reference['sha256'],'Main independent fixture changed')
                golden=read(path);need(reference['count']==len(case['generated_tokens'])and golden['generated_tokens'][:reference['count']]==case['generated_tokens'],
                    'Actual main wire tokens differ from independent fixture')
            match=re.fullmatch(r'(around32|around128|prefix128|prefix512|prefix2047|prefix2048)-t([0-3])(?:-seed-(a|b|zero|all-ones))?(?:-run[12])?',case['label'])
            if match:
                name,code,seed=match.groups();seed=seed or'a';folder='domain-goldens'if name=='around32'else'goldens'
                golden=read(package/'reference/seeded-sampling'/folder/f'{name}-t{code}-seed-{seed}.json')
                need(golden['model_image_sha256']==MODEL and case['generated_tokens']==golden['generated_tokens'],
                     'Recorded candidate main outputs differ from the independent model fixture')
    status=read(package/'evidence/seeded-sampling/current-browser.json')
    need(set(status)==set('schema state image_sha256 model_image_sha256 hardware_inputs_sha256 host_source_inputs archive source_inputs_receipt_sha256 source_finished_receipt_sha256 credited_cases'.split())
         and status['schema']=='long-context-current-browser-status-v4'
         and status['image_sha256']==record['image_sha256']and status['model_image_sha256']==MODEL
         and status['hardware_inputs_sha256']==digest and status['host_source_inputs']==record['host_source_inputs'],
         'Current browser status/image/host binding differs')
    completed=status['state']=='complete'
    if not completed:
        need(status['state']=='pending'and status['archive']is None and status['source_inputs_receipt_sha256']is None
             and status['source_finished_receipt_sha256']is None and status['credited_cases']==0,'Pending browser status credits unperformed work')
    else:
        path=package/'tools/check_long_context_browser.py';need(path.relative_to(package).as_posix()in manifest['files'],'Current browser validator is missing')
        spec=importlib.util.spec_from_file_location('_recipient_current_browser',path);browser=importlib.util.module_from_spec(spec);spec.loader.exec_module(browser)
        result=browser.check(package,require_complete=True)
        need(result['state']=='complete'and result['passed']is True and result['image_sha256']==record['image_sha256']
             and result['credited_cases']==status['credited_cases']>0,'Actual current browser record did not pass')
    selected=manifest['variants']['seeded-sampling'];need(selected['opened_browser_rehearsal_complete']is completed and selected['experimental']is(not completed)
         and selected['formal_replay_of_this_variant']is False and selected['evidence']=='evidence/seeded-sampling/current-candidate-cli.json','Current qualification flags differ from actual browser status')
    archive=target(package,record['historical_release']['path']);need(identity(archive)=={k:record['historical_release'][k]for k in('sha256','bytes')},'Historical release archive changed')
    with zipfile.ZipFile(archive)as z:
        old=json.loads(z.read('MANIFEST.json'));need(hashlib.sha256(z.read('MANIFEST.json')).hexdigest()==record['historical_release']['manifest_sha256']==HISTORICAL_MANIFEST,'Historical release manifest differs')
        need(len(z.namelist())==len(old['files'])+1 and set(z.namelist())==set(old['files'])|{'MANIFEST.json'},'Historical archive file census differs')
        for name,want in old['files'].items():
            relative=PurePosixPath(name);need(not relative.is_absolute()and '..'not in relative.parts,'Unsafe historical archive member')
            raw=z.read(name);need(dict(bytes=len(raw),sha256=hashlib.sha256(raw).hexdigest())==want,'Historical release member changed')
        need(old['files']['prebuilt/seeded-sampling/project/impl/pnr/shared_product.fs']['sha256']==OLD_IMAGE,'Historical0e6 image is missing')
    return dict(schema='long-context-private-recipient-check-v1',bytes_checked=True,recorded_cli_bindings_checked=True,
        image_sha256=record['image_sha256'],files=len(manifest['files'])+1,native_inputs=91,distributed_inputs=87,
        current_browser_state=status['state'],browser_record_passed=completed,
        hardware_access=False,integer_model_replayed=False,solver_replayed=False,browser_rehearsed=False,release_qualified=False)

def main():
    require_v8_baseline_scope()
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--package',type=Path,required=True);p.add_argument('--allow-local-runtime',action='store_true');a=p.parse_args();print(json.dumps(check(a.package,not a.allow_local_runtime),indent=2))
